function isBalanced(str) {
  const stack = [];
  const pairs = {')': '(', ']': '[', '}': '{'};
  for (const c of str) {
    if ('([{'.includes(c)) stack.push(c);
    else if (')]}'.includes(c)) {
      if (stack.pop() !== pairs[c]) return false;
    }
  }
  return stack.length === 0;
}
console.log(isBalanced('{[()]}'));
console.log(isBalanced('{[(])}'));
